 prof={'index':i,'case_id':c['case_id'],'case_input_sha256':digest(c),'case_capture_sha256':sha(f),'original_count':o['occurrences'],'count_definition':o['occurrences_definition'],'source_columns':o['source_columns'],'all_downstream_holds':o['downstream_holds'],'current_owner_files':owners,'primary_capture_inventory':[]}
 context=CAP/f'case-{i:03}-kg-context.json'
