 D.append({'case_id':c['case_id'],'case_input_sha256':digest(c),'source':{k:c[k] for k in ['source','source_case_id','source_label','raw_source_label']},'occurrence_ids':[],'disposition':disp,'reasoning':why,'applicability':'Applies only to this exact source profile and source_case_id, preserving its raw label and frozen count definition. All admitted recipe contexts and embedded downstream holds are bound by the case evidence. Listed owner records are inspected current candidates; a candidate is approved only to the narrow scope expressly stated in reasoning. Registry correspondence does not approve external chemistry, whole owner records, biological claims or complete SSSOM payloads.','evidence_ids':refs[i],'proposal_ids':[],'no_change_reason':nochange,'missing_requirement':missing,'owner_records':owners,'issue_refs':[],'independent_review':{'status':'pending','evidence_ids':[]},'author':'/root/issue_context','allocation_index':i,'original_occurrence_count':o['occurrences'],'original_occurrence_count_definition':o['occurrences_definition']})
